package com.bananalab.lite;
import java.util.*;import org.json.*;
/** Typed grammar of bounded list/text/turn algorithms, emitted as real Java. */
final class MethodProgram{
 final String family,operation,filter;final boolean reverse;
 MethodProgram(String f,String o,String p,boolean r){family=f;operation=o;filter=p;reverse=r;}
 String id(){return family+"_"+operation+"_"+filter+"_"+reverse;}
 JSONObject json()throws Exception{return new JSONObject().put("family",family).put("operation",operation).put("filter",filter).put("reverse",reverse);}
 static List<MethodProgram> grammar(){List<MethodProgram> list=new ArrayList<>();for(String o:new String[]{"sum","count","min","max"})for(String f:new String[]{"all","positive","negative","even","odd"})list.add(new MethodProgram("array",o,f,false));for(String o:new String[]{"none","lower","upper","trim"})for(String f:new String[]{"all","letters","digits"})for(boolean r:new boolean[]{false,true})list.add(new MethodProgram("text",o,f,r));list.add(new MethodProgram("turn","none","all",false));list.add(new MethodProgram("turn","none","all",true));return list;}
 static MethodProgram read(JSONObject data)throws Exception{RuntimeProgram.keys(data,"family","operation","filter","reverse");for(MethodProgram p:grammar())if(p.json().toString().equals(data.toString()))return p;throw new IllegalArgumentException("Programa fuera de la gramática.");}
 static MethodProgram request(String request){String q=ChatLanguage.normalize(request);String residue=q.replaceAll("\\b(?:crea|creame|genera|un|una|el|la|los|las|de|del|en|a|y|que|con|para|metodo|funcion|algoritmo|devuelve|calcula|suma|sumar|sume|sumatoria|cuenta|contar|cantidad|numeros|numero|valores|valor|lista|arreglo|positivos|positivo|negativos|negativo|pares|par|impares|impar|todos|mayor|maximo|menor|minimo|texto|cadena|palabra|invierte|invertir|invertido|inverso|inversa|al|reves|minusculas|mayusculas|letras|digitos|recorta|extremos|trim|alternar|alterna|alternados|turnos|turno|personajes|personaje|hablantes|desde|ultimo|ultima|primero|primera)\\b"," ").trim();if(q.length()>200||!residue.isEmpty())throw new IllegalArgumentException("No puedo especificar todavía esta parte: "+residue+". No generé un cambio parcial.");if(q.matches("(?s).*\\b(?:turnos|turno|personajes|hablantes)\\b.*"))return new MethodProgram("turn","none","all",q.matches("(?s).*\\b(?:ultimo|ultima|inverso|inversa|reves)\\b.*"));if(q.matches("(?s).*\\b(?:lista|arreglo|numeros|valores)\\b.*")){String op=q.matches("(?s).*\\b(?:cuenta|contar|cantidad)\\b.*")?"count":q.matches("(?s).*\\b(?:menor|minimo)\\b.*")?"min":q.matches("(?s).*\\b(?:mayor|maximo)\\b.*")?"max":q.matches("(?s).*\\b(?:suma|sumar|sume|sumatoria)\\b.*")?"sum":"";if(op.isEmpty()||(q.contains("positiv")&&q.contains("negativ")))throw new IllegalArgumentException("Indicá una operación y un filtro.");return new MethodProgram("array",op,q.contains("positiv")?"positive":q.contains("negativ")?"negative":q.contains("impar")?"odd":q.matches("(?s).*\\b(?:par|pares)\\b.*")?"even":"all",false);}if(q.matches("(?s).*\\b(?:texto|cadena|palabra)\\b.*")){if(q.contains("minusculas")&&q.contains("mayusculas")||q.contains("letras")&&q.contains("digitos"))throw new IllegalArgumentException("Elegí una transformación y un filtro.");return new MethodProgram("text",q.contains("minusculas")?"lower":q.contains("mayusculas")?"upper":q.contains("trim")||q.contains("recorta")||q.contains("extremos")?"trim":"none",q.contains("letras")?"letters":q.contains("digitos")?"digits":"all",q.matches("(?s).*\\b(?:invierte|invertir|invertido|inversa|inverso|reves)\\b.*"));}throw new IllegalArgumentException("Necesito una tarea de lista, texto o turnos.");}
 static int[] numbers(String input){String s=input.trim();if(s.startsWith("[")&&s.endsWith("]"))s=s.substring(1,s.length()-1);if(s.length()>1024||s.contains("[")||s.contains("]"))throw new IllegalArgumentException("Lista inválida.");if(s.isEmpty())return new int[0];String[] parts=s.split(",",-1);if(parts.length>128)throw new IllegalArgumentException("Hasta128 números.");int[] out=new int[parts.length];for(int i=0;i<out.length;i++){out[i]=Integer.parseInt(parts[i].trim());if(out[i]<-1000||out[i]>1000)throw new IllegalArgumentException("Valores entre-1000 y1000.");}return out;}
 String body(){if(family.equals("array")){String predicate=filter.equals("positive")?"v>0":filter.equals("negative")?"v<0":filter.equals("even")?"v%2==0":filter.equals("odd")?"v%2!=0":"true",update=operation.equals("sum")?"r+=v;":operation.equals("count")?"r++;":operation.equals("min")?"if(!found||v<r)r=v;found=true;":"if(!found||v>r)r=v;found=true;";return "int[] a=numbers(input);int r=0;boolean found=false;for(int i=0;i<a.length&&i<128;i++){int v=a[i];if("+predicate+"){"+update+"}}return Integer.toString(r);";}if(family.equals("turn"))return "int[] a=numbers(input);if(a.length!=2||a[0]<0||a[0]>31||a[1]<1||a[1]>4)throw new IllegalArgumentException(\"Usá turno0..31 y personajes1..4.\");return Integer.toString("+(reverse?"a[1]-1-a[0]%a[1]":"a[0]%a[1]")+");";String b="if(input.length()>128)throw new IllegalArgumentException(\"Hasta128 caracteres.\");String s=input;";if(!filter.equals("all"))b+="StringBuilder out=new StringBuilder();for(int i=0;i<s.length()&&i<128;i++){char c=s.charAt(i);if(Character."+(filter.equals("letters")?"isLetter":"isDigit")+"(c))out.append(c);}s=out.toString();";if(operation.equals("lower"))b+="s=s.toLowerCase(java.util.Locale.ROOT);";if(operation.equals("upper"))b+="s=s.toUpperCase(java.util.Locale.ROOT);";if(operation.equals("trim"))b+="s=s.trim();";if(reverse)b+="s=new StringBuilder(s).reverse().toString();";return b+"return s;";}
 static String parser(){return "String s=input.trim();if(s.startsWith(\"[\")&&s.endsWith(\"]\"))s=s.substring(1,s.length()-1);if(s.length()>1024||s.contains(\"[\")||s.contains(\"]\"))throw new IllegalArgumentException();if(s.isEmpty())return new int[0];String[] p=s.split(\",\",-1);if(p.length>128)throw new IllegalArgumentException();int[] a=new int[p.length];for(int i=0;i<a.length;i++){a[i]=Integer.parseInt(p[i].trim());if(a[i]<-1000||a[i]>1000)throw new IllegalArgumentException();}return a;";}
 String token()throws Exception{return JavaMethodEditor.hash(id()).substring(0,20);}
 String core()throws Exception{return "package com.bananalab.lite;final class JavaAlgorithm {static String process(String input){"+body()+"}static String kind(){return \""+family+"\";}static String version(){return \""+token()+"\";}static int[] numbers(String input){"+parser()+"}}";}
 String source()throws Exception{return core().replace("package com.bananalab.lite;final class JavaAlgorithm","package com.bananalab.patch;public final class JavaMethodCandidate").replace("static String process(","public static String run(");}
 String oracle(String input){if(family.equals("array")){List<Integer> a=new ArrayList<>();for(int v:numbers(input))if(filter.equals("all")||filter.equals("positive")&&v>0||filter.equals("negative")&&v<0||filter.equals("even")&&(v&1)==0||filter.equals("odd")&&(v&1)!=0)a.add(v);if(operation.equals("count"))return ""+a.size();if(operation.equals("min"))return ""+(a.isEmpty()?0:Collections.min(a));if(operation.equals("max"))return ""+(a.isEmpty()?0:Collections.max(a));int total=0;for(int v:a)total+=v;return ""+total;}if(family.equals("turn")){int[] a=numbers(input);return ""+(reverse?a[1]-1-a[0]%a[1]:a[0]%a[1]);}StringBuilder out=new StringBuilder();for(char c:input.toCharArray())if(filter.equals("all")||filter.equals("letters")&&Character.isLetter(c)||filter.equals("digits")&&Character.isDigit(c))out.append(c);String s=out.toString();if(operation.equals("lower"))s=s.toLowerCase(Locale.ROOT);if(operation.equals("upper"))s=s.toUpperCase(Locale.ROOT);if(operation.equals("trim"))s=s.trim();return reverse?new StringBuilder(s).reverse().toString():s;}
 String[] inputs(boolean hidden){return family.equals("array")?(hidden?new String[]{"-9,-1,2,7","0,0,-2,6","1000,-1000,1,1",""}:new String[]{"-4,0,3,8","-5,-2,1,3","2,5,8","-8,-3,-1"}):family.equals("turn")?(hidden?new String[]{"7,4","31,3","0,1"}:new String[]{"0,2","1,2","2,2"}):(hidden?new String[]{"  a1b2 "," Ñandú3 ","AbBa"}:new String[]{" aB1! ","Z9yx",""});}
 static int check(java.lang.reflect.Method method,MethodProgram goal)throws Exception{for(boolean hidden:new boolean[]{false,true})for(String input:goal.inputs(hidden))if(!Objects.equals(method.invoke(null,new String(input)),goal.oracle(input)))throw new IllegalArgumentException("Falló un caso "+(hidden?"reservado":"visible")+" del contrato.");return goal.inputs(false).length+goal.inputs(true).length;}
}
